```sh
#!/bin/sh
PATH=/usr/bin:/bin
export PATH
LC_ALL=C
export LC_ALL

VMSTAT=/proc/vmstat
BOOT_ID_FILE=/proc/sys/kernel/random/boot_id
THP_DIR=/sys/kernel/mm/transparent_hugepage

collector_error() {
    printf 'event_type=collector_error collection_status=%s error_code=%s\n' "$1" "$2"
    exit 0
}

for path in "$VMSTAT" "$BOOT_ID_FILE" "$THP_DIR/enabled" "$THP_DIR/defrag" "$THP_DIR/khugepaged/defrag"; do
    [ -r "$path" ] || collector_error unreadable required_source_unreadable
done

selected_policy() {
    awk '{ for (i=1; i<=NF; i++) if ($i ~ /^\[.*\]$/) { gsub(/^\[|\]$/, "", $i); print $i; exit } }'
}

IFS= read -r boot_id < "$BOOT_ID_FILE"
thp_enabled_policy=$(selected_policy < "$THP_DIR/enabled")
thp_defrag_policy=$(selected_policy < "$THP_DIR/defrag")
IFS= read -r khugepaged_defrag < "$THP_DIR/khugepaged/defrag"

[ -n "$boot_id" ] || collector_error invalid boot_id_missing
[ -n "$thp_enabled_policy" ] || collector_error unsupported thp_enabled_policy_missing
[ -n "$thp_defrag_policy" ] || collector_error unsupported thp_defrag_policy_missing
case "$khugepaged_defrag" in 0|1) ;; *) collector_error invalid khugepaged_defrag_invalid ;; esac

awk -v boot_id="$boot_id" -v enabled="$thp_enabled_policy" -v defrag="$thp_defrag_policy" -v khugepaged_defrag="$khugepaged_defrag" '
BEGIN {
    wanted["compact_stall"]=1; wanted["compact_success"]=1; wanted["compact_fail"]=1;
    wanted["thp_fault_alloc"]=1; wanted["thp_fault_fallback"]=1;
}
($1 in wanted) { value[$1]=$2 }
END {
    for (name in wanted)
        if (!(name in value) || value[name] !~ /^[0-9]+$/) {
            print "event_type=collector_error collection_status=unsupported error_code=counter_missing_or_nonnumeric";
            exit;
        }
    printf "event_type=thp_defrag_sample collection_status=ok metric_source=proc_vmstat boot_id=%s thp_enabled_policy=%s thp_defrag_policy=%s khugepaged_defrag=%s", boot_id, enabled, defrag, khugepaged_defrag;
    printf " compact_stall=%s compact_success=%s compact_fail=%s", value["compact_stall"], value["compact_success"], value["compact_fail"];
    printf " thp_fault_alloc=%s thp_fault_fallback=%s\n", value["thp_fault_alloc"], value["thp_fault_fallback"];
}' "$VMSTAT"
